import re

from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.pm.http_client import PMLicensedHttpClient
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.cu.utilities.m2m_interface_availability_checker import (
    m2m_interface_availability_check,
)
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage

from taf.gnb.oam.coam.cu.utilities.file_operations import save_bytes_to_file_and_return_path


@auto_token_refresh()
class PMLICENSEDv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = PMLicensedHttpClient(base_url=con_details.base_url,
                                                 connection_alias=con_details.alias)

    @m2m_interface_availability_check
    def get_all_raw_measurement_data(self, target_dir=None, target_file_name=None, timeout=30):
        response = self.local_client.get_all_raw_measurement_data(timeout=timeout)
        content_disposition_name = re.search(pattern=r'filename=[\'"]?([^\'"\s]+)[\'"]?',
                                             string=response.headers["Content-Disposition"]).group(1)

        return save_bytes_to_file_and_return_path(target_dir=target_dir,
                                                  target_file_name=target_file_name if target_file_name else content_disposition_name,
                                                  content=response.content)
